// PV total lifetime energy
// 96: historyPV PowerWh low word (0.1kWh)
// 97: historyPV PowerWh high word (0.1kWh)

msg.baseAddr = 96;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 96,
    quantity: 2
};

return msg;

// PV today energy
// 108: Day PV PowerWh (0.1kWh)

msg.baseAddr = 108;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 108,
    quantity: 1
};

return msg;

// MPPT voltage and current for all 4 channels
// 109: Dc voltage 1 (0.1V)
// 110: Dc current 1 (0.1A)
// 111: Dc voltage 2 (0.1V)
// 112: Dc current 2 (0.1A)
// 113: Dc voltage 3 (0.1V)
// 114: Dc current 3 (0.1A)
// 115: Dc voltage 4 (0.1V)
// 116: Dc current 4 (0.1A)

msg.baseAddr = 109;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 109,
    quantity: 8
};

return msg;

// MPPT power for all 4 channels
// 186: PV1 input power (1W)
// 187: PV2 input power (1W)
// 188: PV3 input power (1W)
// 189: PV4 input power (1W)

msg.baseAddr = 186;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 186,
    quantity: 4
};

return msg;

// Build PvDeviceState from multiple Modbus reads.
//
// Registers:
// 96-97   : Total PV Energy low+high (0.1kWh)
// 108     : Today PV Energy (0.1kWh)
// 109-116 : MPPT1-4 Voltage/Current (0.1V, 0.1A)
// 186-189 : MPPT1-4 Power (1W)
//
// Note: Per-MPPT energy is not available - use totals

let raw = msg.payload;

// node-red-contrib-modbus often sends { data: [...], buffer: ... }
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

// Skip string errors
if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

// Determine which block we just read
let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("PvDeviceState: missing base address on msg");
    return null;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    if (!Number.isFinite(low) || !Number.isFinite(high)) return null;
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials in flow context ----

// Total Energy 96-97
if (baseAddr === 96) {
    const low = data[0] || 0;
    const high = data[1] || 0;
    const totalEnergy = u32(low, high) * 0.1;  // Convert to kWh

    flow.set("pv_part_total_energy", {
        totalPvEnergyKWh: Math.round(totalEnergy * 100) / 100
    });
}

// Today Energy 108
else if (baseAddr === 108) {
    const todayRaw = data[0] || 0;  // 0.1kWh
    const todayEnergy = todayRaw * 0.1;

    flow.set("pv_part_today_energy", {
        todayPvEnergyKWh: Math.round(todayEnergy * 100) / 100
    });
}

// MPPT Voltage/Current 109-116
else if (baseAddr === 109) {
    // data[0] = V1, data[1] = C1, data[2] = V2, data[3] = C2, etc.
    flow.set("pv_part_mppt_vc", {
        mppt1: {
            dcVoltageV: Math.round((data[0] || 0) * 0.1 * 10) / 10,
            dcCurrentA: Math.round((data[1] || 0) * 0.1 * 10) / 10
        },
        mppt2: {
            dcVoltageV: Math.round((data[2] || 0) * 0.1 * 10) / 10,
            dcCurrentA: Math.round((data[3] || 0) * 0.1 * 10) / 10
        },
        mppt3: {
            dcVoltageV: Math.round((data[4] || 0) * 0.1 * 10) / 10,
            dcCurrentA: Math.round((data[5] || 0) * 0.1 * 10) / 10
        },
        mppt4: {
            dcVoltageV: Math.round((data[6] || 0) * 0.1 * 10) / 10,
            dcCurrentA: Math.round((data[7] || 0) * 0.1 * 10) / 10
        }
    });
}

// MPPT Power 186-189
else if (baseAddr === 186) {
    flow.set("pv_part_mppt_power", {
        mppt1Power: data[0] || 0,
        mppt2Power: data[1] || 0,
        mppt3Power: data[2] || 0,
        mppt4Power: data[3] || 0
    });
}
else {
    return null;
}

// ---- Try to assemble full state ----

const totalEnergyPart = flow.get("pv_part_total_energy");
const todayEnergyPart = flow.get("pv_part_today_energy");
const mpptVcPart = flow.get("pv_part_mppt_vc");
const mpptPowerPart = flow.get("pv_part_mppt_power");

// Require all parts
if (!totalEnergyPart || !todayEnergyPart || !mpptVcPart || !mpptPowerPart) {
    return null;
}

// Calculate total PV power (sum of all MPPT powers)
const totalPvPowerW = mpptPowerPart.mppt1Power + mpptPowerPart.mppt2Power + 
                      mpptPowerPart.mppt3Power + mpptPowerPart.mppt4Power;

// Helper: determine if MPPT is active (has voltage or power)
function isActive(voltage, power) {
    return voltage > 0 || power > 0;
}

// Build MPPT array
const mpptArray = [
    {
        pvChannelId: 1,
        isActive: isActive(mpptVcPart.mppt1.dcVoltageV, mpptPowerPart.mppt1Power),
        dcVoltageV: mpptVcPart.mppt1.dcVoltageV,
        dcCurrentA: mpptVcPart.mppt1.dcCurrentA,
        inputPowerW: mpptPowerPart.mppt1Power,
        todayEnergyKWh: todayEnergyPart.todayPvEnergyKWh,  // Use total (per-MPPT not available)
        totalEnergyKWh: totalEnergyPart.totalPvEnergyKWh   // Use total (per-MPPT not available)
    },
    {
        pvChannelId: 2,
        isActive: isActive(mpptVcPart.mppt2.dcVoltageV, mpptPowerPart.mppt2Power),
        dcVoltageV: mpptVcPart.mppt2.dcVoltageV,
        dcCurrentA: mpptVcPart.mppt2.dcCurrentA,
        inputPowerW: mpptPowerPart.mppt2Power,
        todayEnergyKWh: null,  // Not available per MPPT
        totalEnergyKWh: null
    },
    {
        pvChannelId: 3,
        isActive: isActive(mpptVcPart.mppt3.dcVoltageV, mpptPowerPart.mppt3Power),
        dcVoltageV: mpptVcPart.mppt3.dcVoltageV,
        dcCurrentA: mpptVcPart.mppt3.dcCurrentA,
        inputPowerW: mpptPowerPart.mppt3Power,
        todayEnergyKWh: null,
        totalEnergyKWh: null
    },
    {
        pvChannelId: 4,
        isActive: isActive(mpptVcPart.mppt4.dcVoltageV, mpptPowerPart.mppt4Power),
        dcVoltageV: mpptVcPart.mppt4.dcVoltageV,
        dcCurrentA: mpptVcPart.mppt4.dcCurrentA,
        inputPowerW: mpptPowerPart.mppt4Power,
        todayEnergyKWh: null,
        totalEnergyKWh: null
    }
];

// Resolve DeviceId
const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "PvDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    totalPvPowerW: totalPvPowerW,
    todayPvEnergyKWh: todayEnergyPart.todayPvEnergyKWh,
    totalPvEnergyKWh: totalEnergyPart.totalPvEnergyKWh,

    mppt: mpptArray
};

// Clear partials for next cycle
flow.set("pv_part_total_energy", null);
flow.set("pv_part_today_energy", null);
flow.set("pv_part_mppt_vc", null);
flow.set("pv_part_mppt_power", null);

// Keep snapshot in flow
flow.set("pvDeviceSnapshot", state);

// Put result on msg
msg.payload = state;
msg.state = state;

return msg;
